plugins {
    id("com.github.johnrengelman.shadow") version "8.1.1"
    id("dev.architectury.loom")
    id("architectury-plugin")
}

architectury {
    platformSetupLoomIde()
    neoForge()
}

/**
 * Mixin refmap generated by common for Fabric. It translates the mixin targets to
 * intermediary names (net/minecraft/class_310...), but NeoForge runs on Mojang names in
 * dev and in production, so applying it makes every mixin target a class that does not
 * exist and the game crashes at startup. Must match "refmap" in cobblemon_safari.mixins.json.
 */
val fabricOnlyRefmap = "cobblemon_safari-refmap.json"

loom {
    silentMojangMappingsLicense()

    runs {
        configureEach {
            // In dev, common's classes (refmap included) are on the classpath as they are,
            // so stripping the file from the jar is not enough. Without a refmap, Mixin
            // resolves the targets by the Mojang names written in the annotations.
            // Global to the run: it also ignores other mods' refmaps, which is harmless here
            // because every mod in this dev run is mapped to Mojang names.
            property("mixin.env.disableRefMap", "true")
        }
    }
}

repositories {
    maven("https://maven.impactdev.net/repository/development/")
    maven("https://thedarkcolour.github.io/KotlinForForge/")
    maven("https://maven.neoforged.net")
}

val shadowBundle: Configuration by configurations.creating {
    isCanBeConsumed = false
    isCanBeResolved = true
}

dependencies {
    minecraft("net.minecraft:minecraft:${property("minecraft_version")}")
    mappings(loom.officialMojangMappings())
    neoForge("net.neoforged:neoforge:${property("neoforge_version")}")

    modImplementation("com.cobblemon:neoforge:${property("cobblemon_version")}") { isTransitive = false }

    // Cobblemon is written in Kotlin and needs KotlinForForge at runtime.
    forgeRuntimeLibrary("thedarkcolour:kotlinforforge-neoforge:${property("kotlin_for_forge_version")}") {
        exclude("net.neoforged.fancymodloader", "loader")
    }

    implementation(project(":common", configuration = "namedElements"))
    "developmentNeoForge"(project(":common", configuration = "namedElements")) {
        isTransitive = false
    }
    // Architectury's standard NeoForge transform. JEC uses transformProductionFabric
    // here; that happens to work while common has no mixins or platform annotations,
    // but it would break the day one is added.
    shadowBundle(project(":common", configuration = "transformProductionNeoForge"))

    testImplementation("org.junit.jupiter:junit-jupiter-api:${property("junit_version")}")
    testRuntimeOnly("org.junit.jupiter:junit-jupiter-engine:${property("junit_version")}")
}

tasks {
    test {
        useJUnitPlatform()
    }

    processResources {
        inputs.property("version", project.version)

        filesMatching("META-INF/neoforge.mods.toml") {
            expand(project.properties)
        }
    }

    jar {
        archiveBaseName.set("${rootProject.property("archives_base_name")}-${project.name}")
        archiveClassifier.set("dev-slim")
    }

    shadowJar {
        exclude("fabric.mod.json")
        // A missing refmap is not an error for Mixin: it falls back to the names written
        // in the annotations, which are the Mojang names NeoForge runs on.
        exclude(fabricOnlyRefmap)
        archiveClassifier.set("dev-shadow")
        archiveBaseName.set("${rootProject.property("archives_base_name")}-${project.name}")
        configurations = listOf(shadowBundle)
    }

    remapJar {
        dependsOn(shadowJar)
        inputFile.set(shadowJar.flatMap { it.archiveFile })
        archiveBaseName.set("${rootProject.property("archives_base_name")}-${project.name}")
        archiveVersion.set("${rootProject.version}")
    }
}
